121	    public void UpdateSettings(AppSettings settings)
122	    {
123	        var normalized = settings.Normalize();
124	        // GetKeyState is queue-relative: read on the UI caller, not the hook-only thread.
125	        var nativeCapsLockOn = (NativeMethods.GetKeyState((int)NativeMethods.VkCapsLock) & 1) != 0;
126	        PostToHookThread(() =>
127	        {
128	            TraceSettings(after: false);
129	            var wasEnabled = _settings.Enabled;
130	            var wasEmacsEnabled = _settings.Enabled && _settings.EmacsEnabled;
131	            _settings = normalized;
132	            WriteHookStatus("settings changed");
133	
134	            if (!_settings.Enabled || !_settings.EmacsEnabled)
135	            {
136	                if (_emacsState.Disable())
137	                {
138	                    NotifyEmacsModeChanged();
139	                }
140	            }
141	            else if (!wasEmacsEnabled)
142	            {
143	                _emacsState.SetActive(_settings.EmacsInitialMode == EmacsInitialMode.Emacs);
144	                EnsureNativeCapsLockOff(nativeCapsLockOn);
145	                NotifyEmacsModeChanged();
146	            }
147	
148	            if (wasEnabled && !_settings.Enabled)
149	            {
150	                ResetActiveStates(resetEmacsTransient: false, reason: InputTraceReason.Disabled);
151	            }
152	            else if (!wasEnabled && _settings.Enabled)
153	            {
154	                RequestRefresh("enabled");
155	            }
156	            TraceSettings(after: true);
157	        });
158	    }
