160	    private async void PostToHookThread(Action action)
161	    {
162	        if (_disposed)
163	        {
164	            return;
165	        }
166	
167	        try
168	        {
169	            if (_hookThread is not null) await _hookThread.InvokeAsync(action).ConfigureAwait(false);
170	            else action(); // The test platform has no dedicated message loop.
171	        }
172	        catch (Exception exception)
173	        {
174	            DiagnosticLog.Write($"Hook-thread command failed: {exception}");
175	        }
176	    }
