178	    private nint KeyboardHookCallback(int code, nint wParam, nint lParam)
179	    {
180	        var startedAt = Stopwatch.GetTimestamp();
181	        _keyboardCallbackCount++;
182	        if (_inputInjectionDepth > 0) _keyboardCallbacksDuringInjection++;
183	        try
184	        {
185	            return InputTrace.Enabled ? TraceKeyboard(code, wParam, lParam) : KeyboardHookCore(code, wParam, lParam);
186	        }
187	        catch (Exception exception)
188	        {
189	            _refreshRequested = true;
190	            DiagnosticLog.Write($"Keyboard callback failed; renewal requested: {exception}");
191	            return _nextKeyboardHook(code, wParam, lParam);
192	        }
193	        finally
194	        {
195	            var elapsed = Stopwatch.GetElapsedTime(startedAt);
196	            if (elapsed.TotalMilliseconds >= 100)
197	            {
198	                DiagnosticLog.Write($"Slow keyboard callback: {elapsed.TotalMilliseconds:F1} ms.");
199	            }
200	        }
201	    }
202	
203	    private nint KeyboardHookCore(int code, nint wParam, nint lParam)
204	    {
205	        if (code < 0 || _disposed)
206	        {
207	            return ForwardKeyboard(code, wParam, lParam);
208	        }
209	
210	        var data = Marshal.PtrToStructure<NativeMethods.KbdLlHookStruct>(lParam);
211	        if (IsOwnInput(data.ExtraInfo))
212	        {
213	            if (DiagnosticLog.VerboseEnabled) DiagnosticLog.WriteVerbose(
214	                $"Injected keyboard event observed: message=0x{unchecked((int)wParam):X4}, vk=0x{data.VirtualKeyCode:X2}, scan=0x{data.ScanCode:X2}, flags=0x{data.Flags:X2}.");
215	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.OwnInput);
216	        }
217	
218	        var message = unchecked((int)wParam);
219	        var isKeyDown = message is NativeMethods.WmKeyDown or NativeMethods.WmSysKeyDown;
220	        var isKeyUp = message is NativeMethods.WmKeyUp or NativeMethods.WmSysKeyUp;
221	        if (!isKeyDown && !isKeyUp)
222	        {
223	            return ForwardKeyboard(code, wParam, lParam);
224	        }
225	
226	        // These IME commands can remain set in GetAsyncKeyState. Pass them through,
227	        // but do not retain them as held keys or promote pending Alt/Ctrl gestures.
228	        if (KeyHoldPolicy.IsWidthKeyCode(data.VirtualKeyCode) &&
229	            KeyHoldPolicy.IsImeWidthCommand(data.VirtualKeyCode, GetForegroundKeyboardLayout()))
230	        {
231	            _nonAltKeysDown.Remove(data.VirtualKeyCode);
232	            _imeWidthCommandEvents++;
233	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.ImeWidth);
234	        }
235	
236	        var isExtended = (data.Flags & NativeMethods.LlkhfExtended) != 0;
237	
238	        var emacsEnabled = _settings.Enabled && _settings.EmacsEnabled;
239	        if (data.VirtualKeyCode == NativeMethods.VkCapsLock &&
240	            _emacsState.HandleCapsLock(isKeyDown, emacsEnabled, out var modeChanged))
241	        {
242	            ConsumePendingAltGestures();
243	            if (modeChanged)
244	            {
245	                NotifyEmacsModeChanged();
246	            }
247	            return SuppressKeyboardEvent(InputTraceReason.CapsLock);
248	        }
249	
250	        if (data.VirtualKeyCode == NativeMethods.VkLControl ||
251	            data.VirtualKeyCode == NativeMethods.VkControl && !isExtended)
252	        {
253	            return HandleControlEvent(_leftControl, code, wParam, lParam, data, isKeyDown);
254	        }
255	
256	        if (data.VirtualKeyCode == NativeMethods.VkRControl ||
257	            data.VirtualKeyCode == NativeMethods.VkControl && isExtended)
258	        {
259	            return HandleControlEvent(_rightControl, code, wParam, lParam, data, isKeyDown);
260	        }
261	
262	        var modifiers = isKeyDown && emacsEnabled && _emacsState.Active && EmacsBindings.IsSourceKey(data.VirtualKeyCode)
263	            ? GetNavigationModifiers() : NavigationModifiers.None;
264	        if (_emacsState.HandleKey(data.VirtualKeyCode, isKeyDown, emacsEnabled,
265	            modifiers, _settings.EmacsShortcuts, out var binding,
266	            modifiers == NavigationModifiers.None ? null : GetEmacsSideFilter()))
267	        {
268	            if (binding is not null)
269	            {
270	                if ((binding.Modifiers & NavigationModifiers.Alt) != 0)
271	                {
272	                    ConsumePendingAltGestures();
273	                }
274	                if ((binding.Modifiers & NavigationModifiers.Control) != 0)
275	                {
276	                    ConsumePendingControlGestures();
277	                }
278	                SendNavigation(binding);
279	            }
280	            return SuppressKeyboardEvent(InputTraceReason.Emacs);
281	        }
282	
283	        if (!_settings.Enabled)
284	        {
285	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.Inactive);
286	        }
287	
288	        PromotePendingControlsToNative();
289	
290	        if (data.VirtualKeyCode == NativeMethods.VkLMenu ||
291	            data.VirtualKeyCode == NativeMethods.VkMenu && !isExtended)
292	        {
293	            DiagnosticLog.WriteVerbose(
294	                $"Left Alt {(isKeyDown ? "down" : "up")}: vk=0x{data.VirtualKeyCode:X2}, scan=0x{data.ScanCode:X2}, flags=0x{data.Flags:X2}.");
295	            return HandleAltEvent(_leftAlt, code, wParam, lParam, data, isKeyDown);
296	        }
297	
298	        if (data.VirtualKeyCode == NativeMethods.VkRMenu ||
299	            data.VirtualKeyCode == NativeMethods.VkMenu && isExtended)
300	        {
301	            DiagnosticLog.WriteVerbose(
302	                $"Right Alt {(isKeyDown ? "down" : "up")}: vk=0x{data.VirtualKeyCode:X2}, scan=0x{data.ScanCode:X2}, flags=0x{data.Flags:X2}.");
303	            return HandleAltEvent(_rightAlt, code, wParam, lParam, data, isKeyDown);
304	        }
305	
306	        if (_leftAlt.IsDown || _rightAlt.IsDown)
307	        {
308	            if (IsShiftKey(data.VirtualKeyCode) && isKeyDown && CanDeferAltShift())
309	            {
310	                // Alt+< / Alt+> need Shift. Keep pending Alt hidden until the next key.
311	                MarkDeferredShiftChord();
312	            }
313	            else if (!(IsShiftKey(data.VirtualKeyCode) && isKeyUp &&
314	                (_leftAlt.ConsumedByEmacs || _rightAlt.ConsumedByEmacs)))
315	            {
316	                PromotePendingAltsToNative();
317	            }
318	        }
319	
320	        if (isKeyDown)
321	        {
322	            _nonAltKeysDown.Add(data.VirtualKeyCode);
323	        }
324	        else
325	        {
326	            _nonAltKeysDown.Remove(data.VirtualKeyCode);
327	        }
328	
329	        return ForwardKeyboard(code, wParam, lParam);
330	    }
