332	    private nint HandleControlEvent(
333	        DeferredControlState state,
334	        int code,
335	        nint wParam,
336	        nint lParam,
337	        NativeMethods.KbdLlHookStruct data,
338	        bool isKeyDown)
339	    {
340	        if (isKeyDown)
341	        {
342	            if (state.IsDown)
343	            {
344	                return state.OriginalDownPassed
345	                    ? ForwardKeyboard(code, wParam, lParam, InputTraceReason.ControlRepeat)
346	                    : SuppressKeyboardEvent(InputTraceReason.ControlRepeat);
347	            }
348	
349	            state.Start(data.ScanCode, (data.Flags & NativeMethods.LlkhfExtended) != 0);
350	            var canDefer = CanDeferControl(state);
351	            if (!canDefer || IsAnyOtherInputDownForControl())
352	            {
353	                state.OriginalDownPassed = true;
354	                return ForwardKeyboard(code, wParam, lParam, canDefer
355	                    ? InputTraceReason.ControlNativeOtherInput : InputTraceReason.ControlNativeNotDeferrable);
356	            }
357	
358	            var otherControl = state.Side == ModifierSides.Left ? _rightControl : _leftControl;
359	            if (otherControl.IsDown)
360	            {
361	                PromotePendingControlToNative(otherControl);
362	                PromotePendingControlToNative(state);
363	            }
364	            return SuppressKeyboardEvent(InputTraceReason.ControlDeferred);
365	        }
366	
367	        if (!state.IsDown)
368	        {
369	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.ControlUnknownUp);
370	        }
371	
372	        state.IsDown = false;
373	        if (state.OriginalDownPassed)
374	        {
375	            state.Reset();
376	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.ControlPassedUp);
377	        }
378	
379	        if (state.NativeDownSent)
380	        {
381	            SendControl(state, keyUp: true);
382	            state.Reset();
383	            return SuppressKeyboardEvent(InputTraceReason.ControlSentUp);
384	        }
385	
386	        if (!state.ConsumedByEmacs)
387	        {
388	            SendControl(state, keyUp: false);
389	            SendControl(state, keyUp: true);
390	        }
391	        state.Reset();
392	        return SuppressKeyboardEvent(InputTraceReason.ControlTapOrConsumed);
393	    }
