395	    private nint HandleAltEvent(
396	        AltState state,
397	        int code,
398	        nint wParam,
399	        nint lParam,
400	        NativeMethods.KbdLlHookStruct data,
401	        bool isKeyDown)
402	    {
403	        if (isKeyDown)
404	        {
405	            // A down event invalidates release observations, even when it looks like a repeat.
406	            state.ReleaseMonitor.Reset();
407	            if (state.IsDown)
408	            {
409	                if (state.OriginalDownPassed || state.NativeDownSent)
410	                {
411	                    // This may be a new press after a missed up. Forward native Alt repeats
412	                    // too: swallowing this down would leave Windows up while the user holds Alt.
413	                    // Its physical up can now follow the physical down through the hook chain.
414	                    state.OriginalDownPassed = true;
415	                    state.NativeDownSent = false;
416	                    return ForwardKeyboard(code, wParam, lParam, InputTraceReason.AltRepeatNative);
417	                }
418	                return SuppressKeyboardEvent(InputTraceReason.AltRepeatHidden);
419	            }
420	
421	            state.Start(data.ScanCode, (data.Flags & NativeMethods.LlkhfExtended) != 0);
422	
423	            var otherAlt = state.Side == AltSide.Left ? _rightAlt : _leftAlt;
424	            if (otherAlt.IsDown)
425	            {
426	                PromotePendingAltToNative(otherAlt);
427	                PromotePendingAltToNative(state);
428	                return SuppressKeyboardEvent(InputTraceReason.AltDeferred);
429	            }
430	
431	            if (IsAnyNonAltKeyDown())
432	            {
433	                if (IsVirtualKeyDown(NativeMethods.VkShift) && CanDeferAltShift() &&
434	                    !_emacsState.GestureActive && _nonAltKeysDown.All(IsShiftKey))
435	                {
436	                    state.DeferredShiftChord = true;
437	                }
438	                else
439	                {
440	                    state.OriginalDownPassed = true;
441	                    return ForwardKeyboard(code, wParam, lParam, InputTraceReason.AltNative);
442	                }
443	            }
444	
445	            return SuppressKeyboardEvent(InputTraceReason.AltDeferred);
446	        }
447	
448	        if (!state.IsDown)
449	        {
450	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.AltUnknownUp);
451	        }
452	
453	        var heldMilliseconds = Environment.TickCount64 - state.DownAtMilliseconds;
454	        state.IsDown = false;
455	
456	        if (state.OriginalDownPassed)
457	        {
458	            state.Reset();
459	            return ForwardKeyboard(code, wParam, lParam, InputTraceReason.AltPassedUp);
460	        }
461	
462	        if (state.NativeDownSent)
463	        {
464	            DiagnosticLog.WriteVerbose($"{state.Side} Alt used with another input; sending native Alt up.");
465	            SendAlt(state, keyUp: true);
466	            state.Reset();
467	            return SuppressKeyboardEvent(InputTraceReason.AltSentUp);
468	        }
469	
470	        if (state.ConsumedByEmacs)
471	        {
472	            state.Reset();
473	            return SuppressKeyboardEvent(InputTraceReason.AltConsumed);
474	        }
475	
476	        if (state.DeferredShiftChord)
477	        {
478	            // No angle shortcut followed: preserve the native Alt+Shift chord.
479	            SendAltTap(state);
480	            state.Reset();
481	            return SuppressKeyboardEvent(InputTraceReason.AltTap);
482	        }
483	
484	        var longPressEnabled = state.Side == AltSide.Left
485	            ? _settings.LeftAltLongPressEnabled
486	            : _settings.RightAltLongPressEnabled;
487	        var action = AltPressDecision.Decide(
488	            heldMilliseconds,
489	            longPressEnabled,
490	            _settings.LongPressMilliseconds);
491	
492	        if (action == AltPressAction.NativeAlt)
493	        {
494	            DiagnosticLog.WriteVerbose(
495	                $"{state.Side} Alt held for {heldMilliseconds} ms; sending native Alt tap.");
496	            SendAltTap(state);
497	        }
498	        else
499	        {
500	            DiagnosticLog.WriteVerbose(
501	                $"{state.Side} Alt held for {heldMilliseconds} ms; sending {(state.Side == AltSide.Left ? "IME off" : "IME on")} tap.");
502	            SendImeStateTap(state.Side);
503	        }
504	
505	        state.Reset();
506	        return SuppressKeyboardEvent(InputTraceReason.AltTap);
507	    }
