509	    private nint MouseHookCallback(int code, nint wParam, nint lParam)
510	    {
511	        var startedAt = Stopwatch.GetTimestamp();
512	        _mouseCallbackCount++;
513	        try
514	        {
515	            return InputTrace.Enabled ? TraceMouse(code, wParam, lParam) : MouseHookCore(code, wParam, lParam);
516	        }
517	        catch (Exception exception)
518	        {
519	            _refreshRequested = true;
520	            DiagnosticLog.Write($"Mouse callback failed; renewal requested: {exception}");
521	            return _platform.NextMouse(_mouseHook, code, wParam, lParam);
522	        }
523	        finally
524	        {
525	            var elapsed = Stopwatch.GetElapsedTime(startedAt);
526	            if (elapsed.TotalMilliseconds >= 100)
527	            {
528	                DiagnosticLog.Write($"Slow mouse callback: {elapsed.TotalMilliseconds:F1} ms.");
529	            }
530	        }
531	    }
532	
533	    private nint MouseHookCore(int code, nint wParam, nint lParam)
534	    {
535	        if (code >= 0 && !_disposed && _settings.Enabled && IsMouseInteraction(unchecked((int)wParam)))
536	        {
537	            PromotePendingControlsToNative();
538	            PromotePendingAltsToNative();
539	        }
540	
541	        return _platform.NextMouse(_mouseHook, code, wParam, lParam);
542	    }
543	
544	    private void PromotePendingAltsToNative()
545	    {
546	        PromotePendingAltToNative(_leftAlt);
547	        PromotePendingAltToNative(_rightAlt);
548	    }
549	
550	    private void PromotePendingControlsToNative()
551	    {
552	        PromotePendingControlToNative(_leftControl);
553	        PromotePendingControlToNative(_rightControl);
554	    }
555	
556	    private void PromotePendingControlToNative(DeferredControlState state)
557	    {
558	        if (!state.IsDown || state.OriginalDownPassed || state.NativeDownSent)
559	        {
560	            return;
561	        }
562	
563	        TraceState(InputTraceReason.PromoteControl);
564	        SendControl(state, keyUp: false);
565	        state.NativeDownSent = true;
566	        TraceState(InputTraceReason.PromoteControl, after: true);
567	        DiagnosticLog.WriteVerbose($"{state.Side} Ctrl used with native input; sent Ctrl down.");
568	    }
569	
570	    private static bool IsMouseInteraction(int message)
571	    {
572	        return message is
573	            NativeMethods.WmLButtonDown or NativeMethods.WmLButtonUp or
574	            NativeMethods.WmRButtonDown or NativeMethods.WmRButtonUp or
575	            NativeMethods.WmMButtonDown or NativeMethods.WmMButtonUp or
576	            NativeMethods.WmXButtonDown or NativeMethods.WmXButtonUp or
577	            NativeMethods.WmMouseWheel or NativeMethods.WmMouseHWheel;
578	    }
579	
580	    private void PromotePendingAltToNative(AltState state)
581	    {
582	        if (!state.IsDown || state.OriginalDownPassed || state.NativeDownSent)
583	        {
584	            return;
585	        }
586	
587	        TraceState(InputTraceReason.PromoteAlt);
588	        SendAlt(state, keyUp: false);
589	        state.NativeDownSent = true;
590	        TraceState(InputTraceReason.PromoteAlt, after: true);
591	        DiagnosticLog.WriteVerbose($"{state.Side} Alt used with another input; sent native Alt down.");
592	    }
593	
594	    private bool IsAnyNonAltKeyDown()
595	    {
596	        // A missed key-up must not classify every later Alt tap as a chord.
597	        KeyHoldPolicy.PruneNonAltKeys(_nonAltKeysDown, GetForegroundKeyboardLayout(), IsVirtualKeyDown);
598	        return _nonAltKeysDown.Count > 0 || _emacsState.GestureActive ||
599	               IsVirtualKeyDown(NativeMethods.VkShift) ||
600	               IsVirtualKeyDown(NativeMethods.VkControl) ||
601	               IsVirtualKeyDown(NativeMethods.VkLWin) ||
602	               IsVirtualKeyDown(NativeMethods.VkRWin);
603	    }
604	
605	    private bool IsAnyOtherInputDownForControl()
606	    {
607	        KeyHoldPolicy.PruneNonAltKeys(_nonAltKeysDown, GetForegroundKeyboardLayout(), IsVirtualKeyDown);
608	        return _nonAltKeysDown.Count > 0 || _leftAlt.IsDown || _rightAlt.IsDown ||
609	               IsVirtualKeyDown(NativeMethods.VkShift) ||
610	               IsVirtualKeyDown(NativeMethods.VkLWin) || IsVirtualKeyDown(NativeMethods.VkRWin);
611	    }
612	
613	    private bool IsVirtualKeyDown(uint virtualKey)
614	    {
615	        return _platform.IsDown((int)virtualKey);
616	    }
617	
618	    private static nuint GetForegroundKeyboardLayout()
619	    {
620	        var window = NativeMethods.GetForegroundWindow();
