779	    private void SendKeyboardInputsFor(InputTraceReason reason, params NativeMethods.Input[] inputs)
780	    {
781	        var parentBatch = _traceBatch;
782	        _traceBatch = ++_traceBatchSequence;
783	        var started = Stopwatch.GetTimestamp();
784	        var result = new InputSendResult(0, 0);
785	        var completed = false;
786	        _inputInjectionDepth++;
787	        _inputInjectionCalls++;
788	        _maxInputInjectionDepth = Math.Max(_maxInputInjectionDepth, _inputInjectionDepth);
789	        try
790	        {
791	            Trace(new() { Kind = InputTraceKind.SendBegin, Reason = reason, ParentBatch = parentBatch, Requested = inputs.Length });
792	            for (var index = 0; index < inputs.Length; index++)
793	            {
794	                inputs[index].Data.Keyboard.ExtraInfo = NextInputMarker();
795	                var key = inputs[index].Data.Keyboard;
796	                Trace(new() { Kind = InputTraceKind.SendItem, Reason = reason, Index = index,
797	                    Token = TraceToken(key.ExtraInfo), SentScan = key.ScanCode, SentVirtualKey = key.VirtualKey,
798	                    Up = (key.Flags & NativeMethods.KeyeventfKeyUp) != 0, Flags = key.Flags, Own = true });
799	            }
800	            result = _platform.Send(inputs);
801	            completed = true;
802	            if (result.Sent == (uint)inputs.Length)
803	            {
804	                if (DiagnosticLog.VerboseEnabled)
805	                    DiagnosticLog.WriteVerbose($"SendInput succeeded for {inputs.Length} keyboard event(s).");
806	            }
807	            else
808	            {
809	                _inputInjectionFailures++;
810	                DiagnosticLog.Write(
811	                    $"SendInput failed: requested={inputs.Length}, sent={result.Sent}; Windows error={result.Error}.");
812	                InputInjectionFailed?.Invoke(result.Error);
813	            }
814	        }
815	        finally
816	        {
817	            Trace(new() { Kind = InputTraceKind.SendEnd, Reason = reason, ParentBatch = parentBatch,
818	                Requested = inputs.Length, Sent = result.Sent, Error = result.Error, Index = completed ? 1 : 0,
819	                ElapsedTicks = Stopwatch.GetTimestamp() - started });
820	            _inputInjectionDepth--;
821	            _traceBatch = parentBatch;
822	        }
823	    }
