825	    // Sends by virtual key (KEYEVENTF_SCANCODE deliberately omitted) so the IME
826	    // receives VK_IME_ON / VK_IME_OFF regardless of the hardware layout.
827	    private static NativeMethods.Input CreateVirtualKeyInput(ushort virtualKey, bool keyUp)
828	    {
829	        return new NativeMethods.Input
830	        {
831	            Type = NativeMethods.InputKeyboard,
832	            Data = new NativeMethods.InputUnion
833	            {
834	                Keyboard = new NativeMethods.KeyboardInput
835	                {
836	                    VirtualKey = virtualKey,
837	                    Flags = (keyUp ? NativeMethods.KeyeventfKeyUp : 0) |
838	                        (IsExtendedVirtualKey(virtualKey)
839	                            ? NativeMethods.KeyeventfExtendedKey : 0),
840	                    ExtraInfo = OwnInputMarker
841	                }
842	            }
843	        };
844	    }
845	
846	    private static NativeMethods.Input CreateNavigationKeyInput(ushort virtualKey, bool keyUp)
847	    {
848	        var mappedScanCode = NativeMethods.MapVirtualKey(virtualKey, NativeMethods.MapvkVkToVscEx);
849	        var scanCode = (ushort)(mappedScanCode & 0xFF);
850	        var prefix = mappedScanCode & 0xFF00;
851	        var isExtended = prefix is 0xE000 or 0xE100 || IsExtendedVirtualKey(virtualKey);
852	
853	        return CreateScanCodeInput(scanCode, isExtended, keyUp);
854	    }
855	
856	    private static bool IsExtendedVirtualKey(ushort virtualKey) =>
857	        virtualKey is (ushort)Keys.Left or (ushort)Keys.Right or (ushort)Keys.Up or (ushort)Keys.Down or
858	            (ushort)Keys.Home or (ushort)Keys.End or (ushort)Keys.Delete or
859	            (ushort)Keys.RControlKey or (ushort)Keys.RMenu;
860	
861	    private static NativeMethods.Input CreateScanCodeInput(ushort scanCode, bool isExtended, bool keyUp)
862	    {
863	        var flags = NativeMethods.KeyeventfScanCode;
864	        if (isExtended)
865	        {
866	            flags |= NativeMethods.KeyeventfExtendedKey;
867	        }
868	
869	        if (keyUp)
870	        {
871	            flags |= NativeMethods.KeyeventfKeyUp;
872	        }
873	
874	        return new NativeMethods.Input
875	        {
876	            Type = NativeMethods.InputKeyboard,
877	            Data = new NativeMethods.InputUnion
878	            {
879	                Keyboard = new NativeMethods.KeyboardInput
880	                {
881	                    ScanCode = scanCode,
882	                    Flags = flags,
883	                    ExtraInfo = OwnInputMarker
884	                }
885	            }
886	        };
887	    }
