951	    private void MaintainHooks()
952	    {
953	        if (_disposed)
954	        {
955	            return;
956	        }
957	
958	        try
959	        {
960	            ReconcileReleasedAlts();
961	            // Record even when a retained gesture prevents renewal indefinitely.
962	            var now = Environment.TickCount64;
963	            if (now - _lastStatusAtMilliseconds >= 30_000)
964	            {
965	                _lastStatusAtMilliseconds = now;
966	                WriteHookStatus("periodic");
967	            }
968	            var info = new NativeMethods.LastInputInfo
969	            {
970	                Size = (uint)Marshal.SizeOf<NativeMethods.LastInputInfo>()
971	            };
972	            if (!NativeMethods.GetLastInputInfo(ref info))
973	            {
974	                return;
975	            }
976	
977	            var idleMilliseconds = HookMaintenancePolicy.CalculateIdleMilliseconds(
978	                unchecked((uint)Environment.TickCount), info.Time);
979	            var gestureActive = _leftAlt.IsDown || _rightAlt.IsDown ||
980	                _leftControl.IsDown || _rightControl.IsDown || _emacsState.GestureActive;
981	            if (idleMilliseconds < HookMaintenancePolicy.MinimumIdleMilliseconds || gestureActive)
982	            {
983	                return;
984	            }
985	
986	            // Includes real keys, modifiers and mouse buttons; excludes Japanese IME width commands.
987	            var anyKeyDown = KeyHoldPolicy.AnyKeyOrMouseButtonDown(
988	                GetForegroundKeyboardLayout(), IsVirtualKeyDown);
989	
990	            if (HookMaintenancePolicy.ShouldRefresh(
991	                Environment.TickCount64 - _lastRefreshAtMilliseconds,
992	                idleMilliseconds, anyKeyDown, gestureActive, _refreshRequested))
993	            {
994	                ResetActiveStates();
995	                RegisterHooks();
996	            }
997	        }
998	        catch (Exception exception)
999	        {
1000	            _refreshRequested = true;
1001	            DiagnosticLog.Write($"Hook renewal failed; will retry at safe idle: {exception}");
1002	        }
1003	    }
