1034	    private void ReconcileReleasedAlts()
1035	    {
1036	        _altReconcileChecks++;
1037	        // Do not interpret our temporary releases during SendInput as user releases.
1038	        if (_inputInjectionDepth != 0)
1039	        {
1040	            _altReconcileInjectionSkips++;
1041	            if (_leftAlt.IsDown || _rightAlt.IsDown) _altReconcileInjectionSkipsWithAlt++;
1042	            _maxAltReconcileInjectionDepth = Math.Max(_maxAltReconcileInjectionDepth, _inputInjectionDepth);
1043	            _leftAlt.ReleaseMonitor.Reset();
1044	            _rightAlt.ReleaseMonitor.Reset();
1045	            return;
1046	        }
1047	        if (!(_leftAlt.IsDown || _rightAlt.IsDown))
1048	        {
1049	            _leftAlt.ReleaseMonitor.Reset();
1050	            _rightAlt.ReleaseMonitor.Reset();
1051	            return;
1052	        }
1053	        var reliable = AsyncKeyStateAccess.TryReadAlt(out var foreground, out var leftDown, out var rightDown);
1054	        var now = Environment.TickCount64;
1055	        ReconcileReleasedAlt(_leftAlt, reliable, foreground, leftDown, now);
1056	        ReconcileReleasedAlt(_rightAlt, reliable, foreground, rightDown, now);
1057	    }
