1059	    private void ReconcileReleasedAlt(AltState state, bool reliable, nint foreground, bool asyncDown, long now)
1060	    {
1061	        var snapshot = new AltModifierSnapshot(state.IsDown, state.OriginalDownPassed, state.NativeDownSent, asyncDown);
1062	        if (!state.ReleaseMonitor.Observe(snapshot, reliable, foreground, now)) return;
1063	        DiagnosticLog.Write($"Recovered released {state.Side} Alt: originalPassed={state.OriginalDownPassed}, " +
1064	            $"nativeSent={state.NativeDownSent}, heldMs={Environment.TickCount64 - state.DownAtMilliseconds}.");
1065	        // Windows already reports up. Clear bookkeeping without inventing a tap or injecting input.
1066	        TraceState(InputTraceReason.RecoveredAlt);
1067	        state.Reset();
1068	        _altStateRecoveries++;
1069	        TraceState(InputTraceReason.RecoveredAlt, after: true);
1070	        RequestRefresh("released Alt state reconciled");
1071	    }
