71	            if (_settings.EmacsShortcuts.IsEnabled(binding.Shortcut)) shortcuts |= 1u << (int)binding.Shortcut;
72	        var bits = (uint)_settings.EmacsControlSide | (uint)_settings.EmacsAltSide << 2 |
73	            (uint)_settings.EmacsInitialMode << 4 | (_settings.LeftAltLongPressEnabled ? 1u << 5 : 0) |
