1	using System.Diagnostics;
2	using System.Threading.Channels;
3	
4	namespace AltHenkan;
5	
6	internal enum InputTraceKind { KeyBegin, KeyEnd, MouseBegin, MouseEnd, SendBegin, SendItem, SendEnd, State, Boundary, Settings, Status, Fallback }
7	internal enum InputTraceKey { Other, LeftControl, RightControl, LeftAlt, RightAlt, Shift, Windows, CapsLock }
8	internal enum InputTraceVerdict { None, Forwarded, Suppressed, Exception }
9	internal enum InputTraceReason
10	{
11	    None, OwnInput, Inactive, ControlRepeat, ControlNativeNotDeferrable, ControlNativeOtherInput, ControlDeferred, ControlUnknownUp,
12	    ControlPassedUp, ControlSentUp, ControlTapOrConsumed, AltRepeatNative, AltRepeatHidden,
13	    AltNative, AltDeferred, AltUnknownUp, AltPassedUp, AltSentUp, AltConsumed, AltTap,
14	    CapsLock, Emacs, ImeWidth, PromoteControl, PromoteAlt, ConsumeControl, Navigation,
15	    ImeTap, ControlSend, AltSend, CapsReset, Settings, ResetBegin, ResetEnd,
16	    Disabled, Suspend, SessionLock, Renewal, Shutdown, Registered, RecoveredAlt, Maintenance,
17	    Startup, BeforeReset, CallbackFailed, Unregistered
18	}
19	
20	// No ordinary key code, scan code, text, window title, or clipboard is stored here.
21	internal readonly record struct InputTraceSnapshot(uint State, byte AsyncRaw, int Captured, int NonAltKeys);
22	internal readonly record struct InputTraceEvent
23	{
24	    public InputTraceKind Kind { get; init; }
25	    public InputTraceReason Reason { get; init; }
26	    public long Observation { get; init; }
27	    public long Parent { get; init; }
28	    public long Batch { get; init; }
29	    public long ParentBatch { get; init; }
30	    public uint Token { get; init; }
31	    public int Index { get; init; }
32	    public int Depth { get; init; }
33	    public InputTraceKey Key { get; init; }
34	    public bool Up { get; init; }
35	    public uint Flags { get; init; }
36	    public bool Own { get; init; }
37	    public uint EventTime { get; init; }
38	    public InputTraceSnapshot Snapshot { get; init; }
39	    public InputTraceVerdict Verdict { get; init; }
40	    public long Result { get; init; }
41	    public long ElapsedTicks { get; init; }
42	    public int Requested { get; init; }
43	    public uint Sent { get; init; }
44	    public int Error { get; init; }
45	    // Scan codes are populated ONLY for inputs generated by this application.
46	    public ushort SentScan { get; init; }
47	    public ushort SentVirtualKey { get; init; }
48	    public nint Foreground { get; init; }
49	    public uint ForegroundProcess { get; init; }
50	    public uint ForegroundThread { get; init; }
51	    public long KeyboardCallbacks { get; init; }
52	    public long MouseCallbacks { get; init; }
53	    public uint SettingsBits { get; init; }
54	    public int LongPressMilliseconds { get; init; }
55	    public uint Shortcuts { get; init; }
56	}
57	
58	internal static class InputTrace
59	{
60	    private static InputTraceWriter? _writer;
61	    private static long _recordFailures;
62	    public static Guid Session { get; private set; }
63	    public static long RecordFailures => Interlocked.Read(ref _recordFailures);
64	    public static void RecordFailure() => Interlocked.Increment(ref _recordFailures);
65	    public static bool Enabled => Volatile.Read(ref _writer)?.Accepting == true;
66	    public static long Dropped => Volatile.Read(ref _writer)?.Dropped ?? 0;
67	    public static Exception? LastError => Volatile.Read(ref _writer)?.LastError;
68	    public static void Initialize(string path, Guid session)
69	    {
70	        Shutdown();
71	        Session = session;
72	        Interlocked.Exchange(ref _recordFailures, 0);
73	        _writer = new InputTraceWriter(() => new RotatingDiagnosticWriter(path,
74	            4 * 1024 * 1024, 4, flushEveryLine: false), session);
75	    }
76	    public static long Record(in InputTraceEvent entry)
77	    {
78	        var writer = Volatile.Read(ref _writer);
79	        if (writer is null) return 0;
80	        writer.TryWrite(entry, out var sequence);
81	        return sequence;
82	    }
83	    public static void Shutdown() => Interlocked.Exchange(ref _writer, null)?.Dispose();
84	
85	    public static InputTraceKey Classify(uint key, uint flags) => key switch
86	    {
87	        NativeMethods.VkLControl => InputTraceKey.LeftControl,
88	        NativeMethods.VkRControl => InputTraceKey.RightControl,
89	        NativeMethods.VkControl => (flags & NativeMethods.LlkhfExtended) != 0 ? InputTraceKey.RightControl : InputTraceKey.LeftControl,
90	        NativeMethods.VkLMenu => InputTraceKey.LeftAlt,
91	        NativeMethods.VkRMenu => InputTraceKey.RightAlt,
92	        NativeMethods.VkMenu => (flags & NativeMethods.LlkhfExtended) != 0 ? InputTraceKey.RightAlt : InputTraceKey.LeftAlt,
93	        NativeMethods.VkShift or NativeMethods.VkLShift or NativeMethods.VkRShift => InputTraceKey.Shift,
94	        NativeMethods.VkLWin or NativeMethods.VkRWin => InputTraceKey.Windows,
95	        NativeMethods.VkCapsLock => InputTraceKey.CapsLock,
96	        _ => InputTraceKey.Other
97	    };
98	}
99	
100	// Bounded, nonblocking producers. All formatting, file access, and periodic flushing
101	// run on the consumer, independently of the input thread's maintenance timer.
102	internal sealed class InputTraceWriter : IDisposable
103	{
104	    private readonly record struct Entry(long Seq, long Qpc, InputTraceEvent Value);
105	    private readonly Channel<Entry> _queue;
106	    private readonly Task _worker;
107	    private readonly TaskCompletionSource _stop = new(TaskCreationOptions.RunContinuationsAsynchronously);
108	    private readonly Action<string> _report;
109	    private long _sequence;
110	    private long _dropped;
111	    private Exception? _lastError;
112	    private int _accepting = 1;
113	    public bool Accepting => Volatile.Read(ref _accepting) != 0;
114	    public long Dropped => Interlocked.Read(ref _dropped);
115	    public Exception? LastError => Volatile.Read(ref _lastError);
116	    public Task Completion => _worker;
117	
118	    public InputTraceWriter(Func<TextWriter> createWriter, Guid session, int capacity = 8192,
119	        Action<string>? report = null, TimeSpan? retryDelay = null)
120	    {
121	        _report = report ?? DiagnosticLog.Write;
122	        _queue = Channel.CreateBounded<Entry>(new BoundedChannelOptions(capacity)
123	        { SingleReader = true, SingleWriter = false, FullMode = BoundedChannelFullMode.Wait });
124	        var utc = DateTimeOffset.UtcNow;
125	        var qpc = Stopwatch.GetTimestamp();
126	        var header = $"Input trace session={session:N} utc={utc:O} qpc={qpc} frequency={Stopwatch.Frequency} version={typeof(InputTrace).Assembly.GetName().Version} schema=2";
127	        _worker = Task.Run(async () =>
128	        {
129	            TextWriter? writer = null;
130	            long outageStart = 0;
131	            long reportedDrops = 0;
132	            try
133	            {
134	                while (true)
135	                {
136	                    // A dequeued entry may fail to reach disk. Count it, but do not replay:
137	                    // the write may have completed partially before throwing.
138	                    var writingEntry = false;
139	                    try
140	                    {
141	                        if (writer is null)
142	                        {
143	                            writer = createWriter();
144	                            if (writer is RotatingDiagnosticWriter rotating) rotating.SetHeader(header);
145	                            else await writer.WriteLineAsync(header);
146	                            if (outageStart != 0)
147	                            {
148	                                var recoveredAt = Stopwatch.GetTimestamp();
149	                                await writer.WriteLineAsync($"Trace outage: fromQpc={outageStart} toQpc={recoveredAt} observationPaused=True unflushedMayBeLost=True droppedTotal={Dropped}");
150	                                await writer.FlushAsync();
151	                                Report($"Input trace recovered: session={session:N}, fromQpc={outageStart}, toQpc={recoveredAt}, droppedTotal={Dropped}.");
152	                                outageStart = 0;
153	                            }
154	                            Volatile.Write(ref _lastError, null);
155	                            if (!_stop.Task.IsCompleted) Volatile.Write(ref _accepting, 1);
156	                        }
157	                        // Bound each drain so continuous input cannot postpone flushing indefinitely.
158	                        for (var i = 0; i < 8192 && _queue.Reader.TryRead(out var entry); i++)
159	                        {
160	                            writingEntry = true;
161	                            await writer.WriteLineAsync(Format(entry.Seq, entry.Qpc, entry.Value));
162	                            writingEntry = false;
163	                        }
164	                        var drops = Dropped;
165	                        if (drops != reportedDrops)
166	                        {
167	                            await writer.WriteLineAsync($"Trace gap: droppedTotal={drops}, latestSeq={Interlocked.Read(ref _sequence)}");
168	                            reportedDrops = drops;
169	                        }
170	                        await writer.FlushAsync();
171	                        if (_queue.Reader.Completion.IsCompleted)
172	                        {
173	                            await writer.WriteLineAsync($"Input trace ended: latestSeq={Interlocked.Read(ref _sequence)}, droppedTotal={Dropped}");
174	                            await writer.FlushAsync();
175	                            break;
176	                        }
177	                        await Task.WhenAny(Task.Delay(250), _stop.Task);
178	                    }
179	                    catch (Exception exception)
180	                    {
181	                        Volatile.Write(ref _accepting, 0);
182	                        Volatile.Write(ref _lastError, exception);
183	                        if (writingEntry) Interlocked.Increment(ref _dropped);
184	                        if (outageStart == 0)
185	                        {
186	                            outageStart = Stopwatch.GetTimestamp();
187	                            Report($"Input trace write failed: session={session:N}, qpc={outageStart}, latestSeq={Interlocked.Read(ref _sequence)}, unflushedMayBeLost=True. Retrying; observations paused. {exception}");
188	                        }
189	                        try { writer?.Dispose(); } catch { /* Preserve the first write failure. */ }
190	                        writer = null;
191	                        if (_stop.Task.IsCompleted) break;
192	                        await Task.WhenAny(Task.Delay(retryDelay ?? TimeSpan.FromSeconds(1)), _stop.Task);
193	                        if (_stop.Task.IsCompleted) break;
194	                    }
195	                }
196	            }
197	            finally
198	            {
199	                Volatile.Write(ref _accepting, 0);
200	                // At shutdown during an outage, pending entries cannot be saved.
201	                long abandoned = 0;
202	                while (_queue.Reader.TryRead(out _)) abandoned++;
203	                if (abandoned != 0)
204	                {
205	                    Interlocked.Add(ref _dropped, abandoned);
206	                    Report($"Input trace shutdown: abandoned={abandoned}, droppedTotal={Dropped}.");
207	                }
208	                try { writer?.Dispose(); }
209	                catch (Exception exception)
210	                {
211	                    Volatile.Write(ref _lastError, exception);
212	                    Report($"Input trace close failed; unflushedMayBeLost=True. {exception}");
213	                }
214	            }
215	        });
216	    }
217	
218	    private void Report(string message)
219	    {
220	        try { _report(message); } catch { /* Reporting must not terminate the consumer. */ }
221	    }
222	
223	    public bool TryWrite(in InputTraceEvent value) => TryWrite(value, out _);
224	    public bool TryWrite(in InputTraceEvent value, out long sequence)
225	    {
226	        sequence = Interlocked.Increment(ref _sequence);
227	        var entry = new Entry(sequence, Stopwatch.GetTimestamp(), value);
228	        if (Accepting && _queue.Writer.TryWrite(entry)) return true;
229	        Interlocked.Increment(ref _dropped);
230	        return false;
231	    }
232	
233	    internal static string Format(long seq, long qpc, in InputTraceEvent e)
234	    {
235	        var text = $"seq={seq} qpc={qpc} kind={e.Kind} reason={e.Reason} obs={e.Observation} parent={e.Parent} batch={e.Batch} index={e.Index} depth={e.Depth}";
236	        // A SendItem describes the plan, not another state observation.
237	        if (e.Kind != InputTraceKind.SendItem)
238	            text += $" state=0x{e.Snapshot.State:X} asyncRaw=0x{e.Snapshot.AsyncRaw:X} captured={e.Snapshot.Captured} nonAltKeys={e.Snapshot.NonAltKeys}";
239	        if (e.Kind is InputTraceKind.KeyBegin or InputTraceKind.KeyEnd or InputTraceKind.MouseBegin or InputTraceKind.MouseEnd)
240	            text += $" key={e.Key} up={e.Up} flags=0x{e.Flags:X} own={e.Own} token={e.Token} eventTime={e.EventTime} foreground=0x{e.Foreground:X} pid={e.ForegroundProcess} tid={e.ForegroundThread}";
241	        if (e.Kind is InputTraceKind.KeyEnd or InputTraceKind.MouseEnd or InputTraceKind.Fallback)
