103	    public static void Run(Action<string, bool> check)
104	    {
105	        RunAltRepress(check);
106	        // Match 2026-10-11: tracked left Alt and NativeDownSent, but async Alt is up.
107	        var stale = new AltModifierSnapshot(true, false, true, false);
108	        check("Released native Alt is not used as an Emacs modifier", !stale.Active);
109	        check("Released native Alt is not restored after Emacs input", !stale.ShouldRestore);
110	        var binding = EmacsBindings.All.First(b => b.Shortcut == EmacsShortcut.ControlF);
111	        var plan = NavigationInputPlan.Create(binding,
112	            stale.ShouldRestore ? [(ushort)NativeMethods.VkLMenu] : []);
113	        check("Navigation with stale native Alt contains no Alt reinjection",
114	            plan.All(stroke => stroke.VirtualKey != NativeMethods.VkLMenu));
115	        var letter = new EmacsKeyboardState();
116	        letter.SetActive(true);
