122	        {
123	            var held = new AltModifierSnapshot(true, original, !original, true);
124	            var released = held with { AsyncDown = false };
125	            check("Held forwarded/injected Alt still participates in shortcuts", held.Active && held.ShouldRestore);
126	            var heldPlan = NavigationInputPlan.Create(binding, held.ShouldRestore ? [(ushort)NativeMethods.VkLMenu] : []);
127	            check("Held native Alt is released for navigation and restored afterwards",
128	                heldPlan[0] == new NavigationKeyStroke((ushort)NativeMethods.VkLMenu, true) &&
129	                heldPlan[^1] == new NavigationKeyStroke((ushort)NativeMethods.VkLMenu, false));
130	            var monitor = new AltReleaseMonitor();
