166	    private static void RunAltRepress(Action<string, bool> check)
167	    {
168	        const BindingFlags flags = BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public;
169	        var type = typeof(AltInputService);
170	        var stateType = type.GetNestedType("AltState", BindingFlags.NonPublic)!;
171	        var sideType = type.GetNestedType("AltSide", BindingFlags.NonPublic)!;
172	        var handle = type.GetMethod("HandleAltEvent", flags)!;
173	        var reconcile = type.GetMethod("ReconcileReleasedAlt", flags)!;
174	        foreach (var side in new[] { "Left", "Right" })
175	        foreach (var origin in new[] { "injected", "passed", "hidden" })
176	        foreach (var scenario in new[] { "stale before sample", "stale after sample", "held repeat" })
177	        {
178	            // Exercise the actual event handler, replacing only hook forwarding.
179	            // Skip the constructor so no global hooks/timers are installed, and never Dispose
180	            // this synthetic service (which would otherwise send native key releases).
181	            var service = (AltInputService)RuntimeHelpers.GetUninitializedObject(type);
182	            var state = Activator.CreateInstance(stateType, [Enum.Parse(sideType, side)])!;
183	            var forwarded = new List<nint>();
184	            var windowsDown = origin != "hidden" && scenario == "held repeat";
185	            NativeMethods.HookProc next = (code, message, dataPointer) =>
186	            {
187	                forwarded.Add(message);
188	                windowsDown = message == NativeMethods.WmSysKeyDown;
